import { JsonTree } from "@/components/commandly/json-tree";
import { Tool } from "@/components/commandly/types/tool";
import { writeClipboard } from "@/components/commandly/utils/clipboard";
import { collapseUnchanged, diffLines, type DiffLineType } from "@/components/commandly/utils/diff";
import { exportToStructuredJSON } from "@/components/commandly/utils/tool-file";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardAction, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { ScrollArea, ScrollBar } from "@/components/ui/scroll-area";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import { CopyIcon, Edit2Icon, XIcon } from "lucide-react";
import { useMemo, useState } from "react";
import { toast } from "sonner";

interface JsonOutputProps {
  tool: Tool;
  originalTool?: Tool;
  onApply?: (tool: Tool) => void;
}

/** The gutter marker for each kind of diff line. */
const DIFF_MARKER: Record<DiffLineType, string> = { same: "  ", added: "+ ", removed: "- " };

/** The row tones for each kind of diff line. */
const DIFF_TONE: Record<DiffLineType, string> = {
  same: "text-foreground/80",
  added: "bg-green-500/10 text-green-700 dark:text-green-400",
  removed: "bg-red-500/10 text-red-700 dark:text-red-400",
};

export function JsonOutput({ tool, originalTool, onApply }: JsonOutputProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState("");
  const [showDiff, setShowDiff] = useState(true);

  const jsonString = useMemo(() => JSON.stringify(exportToStructuredJSON(tool), null, 2), [tool]);
  const originalJsonString = useMemo(
    () =>
      originalTool ? JSON.stringify(exportToStructuredJSON(originalTool), null, 2) : undefined,
    [originalTool],
  );
  const data = useMemo(() => JSON.parse(jsonString) as unknown, [jsonString]);

  const diff = useMemo(() => {
    if (!originalJsonString || originalJsonString === jsonString) return null;
    return collapseUnchanged(diffLines(originalJsonString, jsonString));
  }, [originalJsonString, jsonString]);

  const diffStats = useMemo(() => {
    if (!diff) return null;
    const added = diff.filter((l) => l.type === "added").length;
    const removed = diff.filter((l) => l.type === "removed").length;
    return { added, removed };
  }, [diff]);

  const handleEditToggle = () => {
    setEditValue(jsonString);
    setIsEditing(true);
  };

  const handleApply = () => {
    if (!onApply) return;
    try {
      const parsed = JSON.parse(editValue) as Tool;
      onApply(parsed);
      setIsEditing(false);
    } catch {
      toast.error("Invalid JSON", { description: "Please fix the JSON before applying." });
    }
  };

  const handleCancel = () => {
    setIsEditing(false);
    setEditValue("");
  };

  return (
    <Card className="max-w-full">
      <CardHeader className="gap-4">
        <CardTitle className="flex min-w-0 flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div className="flex min-w-0 flex-col gap-2 sm:flex-row sm:items-center">
            <span className="text-sm text-muted-foreground">
              Structured JSON output for this tool.
            </span>
          </div>
        </CardTitle>
        <div className="flex shrink-0 items-center gap-3 self-start sm:self-auto">
          {onApply && !isEditing && (
            <CardAction
              className="rounded-md"
              onClick={handleEditToggle}
            >
              <Edit2Icon className="h-4 w-4 dark:stroke-primary" />
            </CardAction>
          )}
          {onApply && isEditing && (
            <CardAction
              className="rounded-md"
              onClick={handleCancel}
            >
              <XIcon className="h-4 w-4 dark:stroke-primary" />
            </CardAction>
          )}
          <CardAction
            className="rounded-md"
            onClick={() => {
              writeClipboard(jsonString).then(
                () => toast("Copied!"),
                () => toast.error("Copy failed"),
              );
            }}
          >
            <CopyIcon className="h-4 w-4 dark:stroke-primary" />
          </CardAction>
        </div>
      </CardHeader>
      <CardContent>
        {diffStats && !isEditing && (
          <div className="mb-2 flex flex-wrap items-center gap-2">
            {diffStats.added > 0 && (
              <Badge
                variant="outline"
                className="border-green-500/40 bg-green-500/10 text-green-600 dark:text-green-400"
              >
                +{diffStats.added} added
              </Badge>
            )}
            {diffStats.removed > 0 && (
              <Badge
                variant="outline"
                className="border-red-500/40 bg-red-500/10 text-red-600 dark:text-red-400"
              >
                -{diffStats.removed} removed
              </Badge>
            )}
            <Button
              variant="ghost"
              size="sm"
              className="h-6 px-2 text-xs sm:ml-auto"
              onClick={() => setShowDiff((v) => !v)}
            >
              {showDiff ? "Full view" : "Diff view"}
            </Button>
          </div>
        )}
        {isEditing ? (
          <div className="flex flex-col gap-2">
            <ScrollArea
              className="max-w-full *:data-radix-scroll-area-viewport:max-h-[calc(100vh-360px)]"
              type="hover"
            >
              <Textarea
                className="min-h-80 font-mono text-sm sm:min-h-[calc(100vh-400px)]"
                value={editValue}
                onChange={(e) => setEditValue(e.target.value)}
                spellCheck={false}
              />
              <ScrollBar orientation="vertical" />
              <ScrollBar orientation="horizontal" />
            </ScrollArea>
            <div className="flex justify-end gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={handleCancel}
              >
                Cancel
              </Button>
              <Button
                size="sm"
                onClick={handleApply}
              >
                Apply
              </Button>
            </div>
          </div>
        ) : diff && showDiff ? (
          <ScrollArea
            className="max-w-full *:data-radix-scroll-area-viewport:max-h-[calc(100vh-320px)]"
            type="hover"
          >
            <pre className="w-fit min-w-full rounded-md font-mono text-sm whitespace-pre">
              {diff.map((row, idx) =>
                row.type === "gap" ? (
                  <div
                    key={idx}
                    className="px-1 text-muted-foreground/70"
                  >
                    … {row.count} unchanged {row.count === 1 ? "line" : "lines"}
                  </div>
                ) : (
                  <div
                    key={idx}
                    className={cn("px-1", DIFF_TONE[row.type])}
                  >
                    <span className="opacity-50 select-none">{DIFF_MARKER[row.type]}</span>
                    {row.text}
                  </div>
                ),
              )}
            </pre>
            <ScrollBar orientation="vertical" />
            <ScrollBar orientation="horizontal" />
          </ScrollArea>
        ) : (
          <JsonTree data={data} />
        )}
      </CardContent>
    </Card>
  );
}

import { writeClipboard } from "@/components/commandly/utils/clipboard";
import {
  allBranches,
  branchesToDepth,
  childPath,
  copyText,
  countLabel,
  entries,
  isBranch,
  primitiveText,
  searchJson,
  type JsonValueType,
  typeOf,
  within,
} from "@/components/commandly/utils/json-tree";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import {
  ChevronDownIcon,
  ChevronRightIcon,
  ChevronsDownUpIcon,
  ChevronsUpDownIcon,
  ChevronUpIcon,
  CopyIcon,
  Link2Icon,
  SearchIcon,
} from "lucide-react";
import type { KeyboardEvent as ReactKeyboardEvent, ReactNode } from "react";
import { useCallback, useId, useLayoutEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";

const INDENT = 14;

const VALUE_CLASS: Record<JsonValueType, string> = {
  object: "text-sky-600 dark:text-sky-400",
  array: "text-sky-600 dark:text-sky-400",
  string: "text-emerald-600 dark:text-emerald-400",
  number: "text-amber-600 dark:text-amber-400",
  boolean: "text-violet-600 dark:text-violet-400",
  null: "text-muted-foreground italic",
  other: "text-muted-foreground",
};

function Highlight({ text, needle, current }: { text: string; needle: string; current: boolean }) {
  if (!needle) return <>{text}</>;
  const lower = text.toLowerCase();
  const parts: ReactNode[] = [];
  let from = 0;
  let at = lower.indexOf(needle);
  while (at !== -1) {
    if (at > from) parts.push(text.slice(from, at));
    parts.push(
      <mark
        key={at}
        className={cn(
          "rounded-[2px] bg-yellow-300/60 text-inherit dark:bg-yellow-500/40",
          current && "bg-orange-400/70 dark:bg-orange-500/60",
        )}
      >
        {text.slice(at, at + needle.length)}
      </mark>,
    );
    from = at + needle.length;
    at = lower.indexOf(needle, from);
  }
  if (from < text.length) parts.push(text.slice(from));
  return <>{parts}</>;
}

type TreeRow = {
  id: string;
  kind: "node" | "more";
  level: number;
  name: string | number | null;
  value: unknown;
  type: JsonValueType;
  count: number;
  open: boolean;
  parent: string | null;
  posinset: number;
  setsize: number;
  hidden?: number;
};

export interface JsonTreeProps {
  data: unknown;
  rootName?: string;
  defaultExpandDepth?: number;
  pageSize?: number;
  className?: string;
}

function IconAction({
  label,
  onClick,
  disabled,
  tabIndex,
  children,
}: {
  label: string;
  onClick: () => void;
  disabled?: boolean;
  tabIndex?: number;
  children: ReactNode;
}) {
  return (
    <Button
      type="button"
      variant="ghost"
      size="icon-xs"
      aria-label={label}
      title={label}
      disabled={disabled}
      tabIndex={tabIndex}
      className="text-muted-foreground"
      onClick={(event) => {
        event.stopPropagation();
        onClick();
      }}
    >
      {children}
    </Button>
  );
}

export function JsonTree({
  data,
  rootName = "root",
  defaultExpandDepth = 2,
  pageSize = 50,
  className,
}: JsonTreeProps) {
  const treeId = useId();
  const searchRef = useRef<HTMLInputElement>(null);
  const rowRefs = useRef(new Map<string, HTMLDivElement>());

  const [expanded, setExpanded] = useState<string[]>(() =>
    branchesToDepth(data, rootName, defaultExpandDepth),
  );
  const base = useMemo(() => new Set(expanded), [expanded]);

  const [query, setQuery] = useState("");
  const needle = query.trim().toLowerCase();
  const search = useMemo(
    () => (needle ? searchJson(data, rootName, needle) : null),
    [data, needle, rootName],
  );
  const [closedWhileSearching, setClosedWhileSearching] = useState<{
    needle: string;
    ids: Set<string>;
  }>({ needle: "", ids: new Set<string>() });
  const closed = closedWhileSearching.needle === needle ? closedWhileSearching.ids : null;
  const [matchIndex, setMatchIndex] = useState(0);
  const matches = search?.matches ?? [];
  const matchCount = matches.length;
  const matchSet = useMemo(() => new Set(search?.matches ?? []), [search]);
  const currentMatch = matchCount ? matches[Math.min(matchIndex, matchCount - 1)] : null;

  const isOpen = useCallback(
    (id: string) => (search?.ancestors.has(id) ? !closed?.has(id) : base.has(id)),
    [base, closed, search],
  );

  const [pages, setPages] = useState<Record<string, number>>({});
  const limitOf = useCallback(
    (id: string) => Math.max((pages[id] ?? 1) * pageSize, search?.needed.get(id) ?? 0),
    [pageSize, pages, search],
  );

  const rows = useMemo(() => {
    const out: TreeRow[] = [];
    const visit = (
      value: unknown,
      id: string,
      name: string | number | null,
      level: number,
      parent: string | null,
      posinset: number,
      setsize: number,
    ) => {
      const type = typeOf(value);
      const list = isBranch(type) ? entries(value) : [];
      const open = isBranch(type) && isOpen(id);
      out.push({
        id,
        kind: "node",
        level,
        name,
        value,
        type,
        count: list.length,
        open,
        parent,
        posinset,
        setsize,
      });
      if (!open) return;
      const shown = list.slice(0, limitOf(id));
      const hidden = list.length - shown.length;
      const size = shown.length + (hidden > 0 ? 1 : 0);
      shown.forEach(([key, child], index) =>
        visit(child, childPath(id, key), key, level + 1, id, index + 1, size),
      );
      if (hidden > 0) {
        out.push({
          id: `${id}::more`,
          kind: "more",
          level: level + 1,
          name: null,
          value: null,
          type: "other",
          count: 0,
          open: false,
          parent: id,
          posinset: size,
          setsize: size,
          hidden,
        });
      }
    };
    visit(data, rootName, null, 1, null, 1, 1);
    return out;
  }, [data, isOpen, limitOf, rootName]);

  const [activeRaw, setActiveRaw] = useState(rootName);
  const active = useMemo(() => {
    if (rows.some((row) => row.id === activeRaw)) return activeRaw;
    let best = rootName;
    for (const row of rows) {
      if (row.kind === "node" && within(row.id, activeRaw) && row.id.length > best.length) {
        best = row.id;
      }
    }
    return best;
  }, [activeRaw, rootName, rows]);
  const activeIndex = Math.max(
    0,
    rows.findIndex((row) => row.id === active),
  );
  const activeRow = rows[activeIndex];

  const pendingFocus = useRef(false);
  const pendingReveal = useRef(false);

  useLayoutEffect(() => {
    if (pendingFocus.current) {
      pendingFocus.current = false;
      rowRefs.current.get(active)?.focus({ preventScroll: true });
    }
    if (pendingReveal.current) {
      pendingReveal.current = false;
      rowRefs.current.get(active)?.scrollIntoView({ block: "nearest" });
    }
  }, [active, rows]);

  const moveTo = (id: string, focus = true, reveal = true) => {
    if (id === activeRaw) {
      if (focus) rowRefs.current.get(id)?.focus({ preventScroll: true });
      if (reveal) rowRefs.current.get(id)?.scrollIntoView({ block: "nearest" });
      return;
    }
    pendingFocus.current = focus;
    pendingReveal.current = reveal;
    setActiveRaw(id);
  };

  // Reveal the first match once the search has recomputed for the new query.
  const revealedFor = useRef<string | null>(null);
  useLayoutEffect(() => {
    if (revealedFor.current === needle) return;
    revealedFor.current = needle;
    const first = search?.matches[0];
    if (!first) return;
    pendingReveal.current = true;
    setActiveRaw(first);
  }, [needle, search]);

  const toggle = (id: string, next?: boolean) => {
    const open = isOpen(id);
    const want = next ?? !open;
    if (want === open) return;
    if (search?.ancestors.has(id)) {
      const ids = new Set(closed ?? []);
      if (want) ids.delete(id);
      else ids.add(id);
      setClosedWhileSearching({ needle, ids });
      if (want && !base.has(id)) setExpanded([...base, id]);
      return;
    }
    setExpanded(want ? [...base, id] : [...base].filter((item) => item !== id));
  };

  const expandAll = () => {
    setExpanded(allBranches(data, rootName));
    setClosedWhileSearching({ needle, ids: new Set<string>() });
    setPages({});
    moveTo(active, false);
  };

  const collapseAll = () => {
    setExpanded(isBranch(typeOf(data)) ? [rootName] : []);
    setClosedWhileSearching({
      needle,
      ids: new Set([...(search?.ancestors ?? [])].filter((id) => id !== rootName)),
    });
    setPages({});
    moveTo(rootName, false, false);
  };

  const showMore = (parent: string) =>
    setPages((current) => ({ ...current, [parent]: Math.ceil(limitOf(parent) / pageSize) + 1 }));

  const copy = (row: TreeRow, kind: "value" | "path") => {
    const text = kind === "path" ? row.id : copyText(row.value, row.type);
    writeClipboard(text).then(
      () => toast(kind === "path" ? "Copied path" : "Copied value"),
      () => toast.error("Copy failed"),
    );
  };

  const stepMatch = (step: number) => {
    if (!matchCount) return;
    const next =
      (((Math.min(matchIndex, matchCount - 1) + step) % matchCount) + matchCount) % matchCount;
    setMatchIndex(next);
    moveTo(matches[next], false);
  };

  const onQuery = (next: string) => {
    setQuery(next);
    setMatchIndex(0);
  };

  const onSearchKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Enter") {
      event.preventDefault();
      stepMatch(event.shiftKey ? -1 : 1);
    } else if (event.key === "Escape" && query) {
      event.preventDefault();
      event.stopPropagation();
      onQuery("");
    } else if (event.key === "ArrowDown") {
      event.preventDefault();
      moveTo(active);
    }
  };

  const onTreeKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
    const row = rows[activeIndex];
    if (!row || event.altKey) return;
    const mod = event.metaKey || event.ctrlKey;
    if (mod && event.key.toLowerCase() === "c") {
      if (row.kind === "node" && !window.getSelection()?.toString()) {
        event.preventDefault();
        copy(row, event.shiftKey ? "path" : "value");
      }
      return;
    }
    if (mod) return;
    const go = (index: number) => {
      event.preventDefault();
      const target = rows[Math.max(0, Math.min(rows.length - 1, index))];
      if (target) moveTo(target.id);
    };
    switch (event.key) {
      case "ArrowDown":
        go(activeIndex + 1);
        break;
      case "ArrowUp":
        go(activeIndex - 1);
        break;
      case "Home":
        go(0);
        break;
      case "End":
        go(rows.length - 1);
        break;
      case "ArrowRight":
        event.preventDefault();
        if (row.kind === "node" && isBranch(row.type)) {
          if (!row.open) toggle(row.id, true);
          else if (row.count) go(activeIndex + 1);
        }
        break;
      case "ArrowLeft":
        event.preventDefault();
        if (row.kind === "node" && row.open) toggle(row.id, false);
        else if (row.parent) moveTo(row.parent);
        break;
      case "Enter":
      case " ":
        event.preventDefault();
        if (row.kind === "more") showMore(row.parent ?? rootName);
        else if (isBranch(row.type)) toggle(row.id);
        break;
      case "/":
        event.preventDefault();
        searchRef.current?.focus();
        searchRef.current?.select();
        break;
      default:
        break;
    }
  };

  const describe = (row: TreeRow) => {
    const name = row.name === null ? rootName : String(row.name);
    if (row.kind === "more") {
      return `Show ${Math.min(pageSize, row.hidden ?? 0)} more, ${row.hidden} hidden`;
    }
    if (isBranch(row.type)) return `${name}, ${row.type}, ${countLabel(row.type, row.count)}`;
    const text = primitiveText(row.value, row.type);
    return `${name}: ${text.length > 60 ? `${text.slice(0, 60)}…` : text}`;
  };

  const pathOf = (row: TreeRow) => (row.kind === "node" ? row.id : (row.parent ?? ""));

  return (
    <div className={cn("flex flex-col gap-3", className)}>
      <div className="flex flex-wrap items-center gap-2">
        <label className="relative flex h-8 min-w-0 flex-1 items-center">
          <SearchIcon
            className="pointer-events-none absolute left-2 size-3.5 text-muted-foreground"
            aria-hidden="true"
          />
          <input
            ref={searchRef}
            type="search"
            value={query}
            onChange={(event) => onQuery(event.target.value)}
            onKeyDown={onSearchKeyDown}
            placeholder="Search keys and values"
            aria-label="Search JSON"
            aria-controls={treeId}
            spellCheck={false}
            autoComplete="off"
            className={cn(
              "h-8 w-full rounded-lg border border-input bg-transparent pr-16 pl-7 text-sm outline-none",
              "placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50",
              "[&::-webkit-search-cancel-button]:hidden",
            )}
          />
          {needle ? (
            <span className="absolute right-1 flex items-center gap-0.5">
              <span
                className="px-1 text-xs text-muted-foreground tabular-nums"
                aria-live="polite"
              >
                {matchCount ? `${Math.min(matchIndex, matchCount - 1) + 1}/${matchCount}` : "0/0"}
              </span>
              <IconAction
                label="Previous match"
                disabled={!matchCount}
                onClick={() => stepMatch(-1)}
              >
                <ChevronUpIcon />
              </IconAction>
              <IconAction
                label="Next match"
                disabled={!matchCount}
                onClick={() => stepMatch(1)}
              >
                <ChevronDownIcon />
              </IconAction>
            </span>
          ) : null}
        </label>
        <div className="flex shrink-0 items-center gap-1">
          <IconAction
            label="Expand all"
            onClick={expandAll}
          >
            <ChevronsUpDownIcon />
          </IconAction>
          <IconAction
            label="Collapse all"
            onClick={collapseAll}
          >
            <ChevronsDownUpIcon />
          </IconAction>
        </div>
      </div>

      <div className="max-h-[calc(100vh-420px)] overflow-auto rounded-lg border">
        <div
          id={treeId}
          role="tree"
          aria-label="Tool JSON"
          onKeyDown={onTreeKeyDown}
          className="w-fit min-w-full py-1 outline-none"
        >
          {rows.map((row) => {
            const isActive = row.id === active;
            const branch = isBranch(row.type);
            const mark = search && row.kind === "node" && matchSet.has(row.id) ? needle : "";
            const current = row.id === currentMatch;
            return (
              <div
                key={row.id}
                ref={(node) => {
                  if (node) rowRefs.current.set(row.id, node);
                  else rowRefs.current.delete(row.id);
                }}
                role="treeitem"
                tabIndex={isActive ? 0 : -1}
                aria-level={row.level}
                aria-posinset={row.posinset}
                aria-setsize={row.setsize}
                aria-expanded={row.kind === "node" && branch ? row.open : undefined}
                aria-selected={isActive}
                aria-label={describe(row)}
                className={cn(
                  "group relative flex h-7.5 items-center gap-1 pr-1 text-sm outline-none",
                  "focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:ring-inset",
                  isActive ? "bg-accent/60" : "hover:bg-muted/60",
                )}
                style={{ paddingLeft: (row.level - 1) * INDENT + 4 }}
                onFocus={(event) => {
                  if (event.target === event.currentTarget && row.id !== active) {
                    setActiveRaw(row.id);
                  }
                }}
                onClick={() => {
                  if (row.kind === "more") {
                    showMore(row.parent ?? rootName);
                    moveTo(row.id);
                    return;
                  }
                  if (branch) toggle(row.id);
                  moveTo(row.id);
                }}
              >
                {row.kind === "more" ? (
                  <span className="flex items-center gap-2 text-muted-foreground">
                    <span>Show {Math.min(pageSize, row.hidden ?? 0)} more</span>
                    <span className="text-xs">{row.hidden} hidden</span>
                  </span>
                ) : (
                  <>
                    <span className="flex size-4 shrink-0 items-center justify-center text-muted-foreground">
                      {branch ? (
                        <ChevronRightIcon
                          className={cn("size-3.5 transition-transform", row.open && "rotate-90")}
                          aria-hidden="true"
                        />
                      ) : null}
                    </span>
                    <span
                      className={cn(
                        "shrink-0 font-medium",
                        typeof row.name === "number" && "text-muted-foreground",
                      )}
                    >
                      {row.name === null ? (
                        rootName
                      ) : typeof row.name === "number" ? (
                        row.name
                      ) : (
                        <Highlight
                          text={row.name}
                          needle={mark}
                          current={current}
                        />
                      )}
                    </span>
                    <span
                      className="text-muted-foreground"
                      aria-hidden="true"
                    >
                      {row.name === null && branch ? "" : ":"}
                    </span>
                    {branch ? (
                      <span className="flex min-w-0 items-baseline gap-2">
                        {!row.open ? (
                          <span className="truncate text-muted-foreground">
                            {row.type === "array"
                              ? "[…]"
                              : `{ ${entries(row.value)
                                  .slice(0, 3)
                                  .map(([key]) => key)
                                  .join(", ")}${row.count > 3 ? ", …" : ""} }`}
                          </span>
                        ) : null}
                        <span className="shrink-0 text-xs text-muted-foreground">
                          {countLabel(row.type, row.count)}
                        </span>
                      </span>
                    ) : (
                      <span
                        className={cn("min-w-0 truncate font-mono", VALUE_CLASS[row.type])}
                        title={
                          row.type === "string" && (row.value as string).length > 40
                            ? (row.value as string)
                            : undefined
                        }
                      >
                        {row.type === "string" ? (
                          <>
                            &quot;
                            <Highlight
                              text={row.value as string}
                              needle={mark}
                              current={current}
                            />
                            &quot;
                          </>
                        ) : (
                          <Highlight
                            text={primitiveText(row.value, row.type)}
                            needle={mark}
                            current={current}
                          />
                        )}
                      </span>
                    )}
                    <span
                      className={cn(
                        "ml-auto flex shrink-0 items-center gap-0.5",
                        isActive
                          ? "opacity-100"
                          : "opacity-0 group-focus-within:opacity-100 group-hover:opacity-100",
                      )}
                    >
                      <IconAction
                        label="Copy value"
                        tabIndex={-1}
                        onClick={() => copy(row, "value")}
                      >
                        <CopyIcon />
                      </IconAction>
                      <IconAction
                        label="Copy path"
                        tabIndex={-1}
                        onClick={() => copy(row, "path")}
                      >
                        <Link2Icon />
                      </IconAction>
                    </span>
                  </>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {activeRow ? (
        <div className="flex items-center gap-2 rounded-lg border bg-muted/40 px-2 py-1.5">
          <code
            className="min-w-0 flex-1 truncate font-mono text-xs text-muted-foreground"
            title={pathOf(activeRow)}
          >
            {pathOf(activeRow)}
          </code>
          <span className="shrink-0 text-xs text-muted-foreground">
            {activeRow.kind === "node"
              ? isBranch(activeRow.type)
                ? `${activeRow.type}, ${countLabel(activeRow.type, activeRow.count)}`
                : activeRow.type
              : "page"}
          </span>
          {activeRow.kind === "node" ? (
            <IconAction
              label="Copy path"
              tabIndex={-1}
              onClick={() => copy(activeRow, "path")}
            >
              <CopyIcon />
            </IconAction>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

export interface ToolInfo {
  /** A brief human-readable description of what the tool does. */
  description?: string;
  /** The version string of the tool (e.g. "1.0.0"). */
  version?: string;
  /** The homepage or documentation URL for the tool. */
  url?: string;
}

export interface Command {
  /** Unique identifier for this command within the tool. */
  key: string;
  /** Human-readable display name of the command. */
  displayName: string;
  /** Alternate spellings that invoke this command in place of its name. */
  aliases?: string[];
  /** Brief description of what this command does. */
  description?: string;
  /** Whether this command opens an interactive session or prompt. */
  interactive?: boolean;
  /** Display sort position relative to sibling commands. */
  sortOrder?: number;
  /** Parameters accepted by this command. Keys are unique among them. Omit for grouping commands. */
  parameters?: Parameter[];
  /** Groups of this command's parameters with mutual exclusion or required-one-of constraints. */
  exclusionGroups?: ExclusionGroup[];
  /** Subcommands nested beneath this command. */
  commands?: Command[];
}

export type InstallationMethod = "package_manager" | "binary" | "docker" | "script";

export interface InstallationSource {
  /** Unique identifier for this installation source within the tool. */
  key: string;
  /** How the tool is installed. */
  method: InstallationMethod;
  /** Package manager name, set only when method is "package_manager" (e.g. "brew", "go"). */
  manager?: string;
  /** The command that installs the tool. */
  command: string;
  /** Documentation URL describing this installation method. */
  url?: string;
  /** Platforms this installation method applies to. */
  os?: Array<"linux" | "macos" | "windows">;
  /** Additional context for this installation source. */
  note?: string;
}

export interface Installation {
  /** The list of documented ways to install the tool. */
  sources: InstallationSource[];
}

export interface InstallationMethodOption {
  method: InstallationMethod;
  /** Human-readable label for the method. */
  label: string;
}

/** The methods in presentation order; a new method must be given a position here. */
export const INSTALLATION_METHODS: InstallationMethodOption[] = [
  { method: "package_manager", label: "Package manager" },
  { method: "binary", label: "Release binary" },
  { method: "docker", label: "Docker" },
  { method: "script", label: "Script" },
];

export interface ParameterEnumValue {
  /** The raw value passed to the CLI for this choice. */
  value: string;
  /** Human-readable label shown to the user for this enum choice. */
  displayName: string;
  /** Description of what this enum value does or represents. */
  description?: string;
  /** Whether this is the default selection when no value is provided. */
  isDefault?: boolean;
  /** Display sort position relative to sibling enum values. */
  sortOrder?: number;
}

export interface ParameterEnumValues {
  /** The list of allowed enum choices. */
  values: ParameterEnumValue[];
  /** Whether the user can select multiple values at once. */
  allowMultiple?: boolean;
  /** Separator character used when joining multiple selected values. */
  separator?: string;
}

export type ParameterValidationType =
  | "min_length"
  | "max_length"
  | "min_value"
  | "max_value"
  | "regex";

export interface ParameterValidation {
  /** Unique identifier for this validation rule. */
  key: string;
  /** The type of validation to apply. */
  validationType: ParameterValidationType;
  /** The value to validate against (e.g. the max length number, or a regex pattern). */
  validationValue: string;
  /** The error message to display when validation fails. */
  errorMessage: string;
}

export type ParameterDependencyType = "requires" | "conflicts_with";

export interface ParameterDependency {
  /** Unique identifier for this dependency rule. */
  key: string;
  /** Key of the parameter that owns this dependency. */
  parameterKey: string;
  /** Key of the parameter this dependency references. */
  dependsOnParameterKey: string;
  /** Whether this parameter requires or conflicts with the referenced parameter. */
  dependencyType: ParameterDependencyType;
  /** Optional value that the referenced parameter must have for this dependency to apply. */
  conditionValue?: string;
}

export type ParameterValue = string | number | boolean | string[];

// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface ToolMetadata {}

// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface ParameterMetadata {
  /** Arbitrary tags for categorising or filtering parameters. */
  tags?: string[];
}

export type ParameterType = "Flag" | "Option" | "Argument";

export type ParameterDataType = "String" | "Number" | "Boolean" | "Enum";

export interface Parameter {
  /** Unique identifier among its command's parameters. For flags and options this is the full flag, dashes included (e.g. "--output", "-list"). */
  key: string;
  /** Human-readable display name of the parameter. */
  displayName: string;
  /** Brief description of what this parameter does or accepts. */
  description?: string;
  /** Optional grouping label for organising related parameters in the UI. */
  group?: string;
  /** Additional metadata such as tags. */
  metadata?: ParameterMetadata;
  /** Whether this is a boolean flag, a key-value option, or a positional argument. */
  parameterType: ParameterType;
  /** The data type of the parameter's value. */
  dataType: ParameterDataType;
  /** Whether the user must provide this parameter. */
  isRequired?: boolean;
  /** Whether this parameter can be specified multiple times. */
  isRepeatable?: boolean;
  /** Short names and other alternate invocation forms (e.g. ["-o"]). The full flag is `key`. */
  aliases?: string[];
  /** Whether this parameter is also accessible from the subcommands of its command, recursively. */
  recursive?: boolean;
  /** Zero-based position index for positional arguments. */
  position?: number;
  /** Display sort position relative to sibling parameters. */
  sortOrder?: number;
  /** Separator character used when the option accepts multiple values in one argument (e.g. ","). */
  arraySeparator?: string;
  /** Separator between key and value for key=value style options (e.g. "="). */
  keyValueSeparator?: string;
  /** Allowed enum choices when dataType is "Enum". */
  enum?: ParameterEnumValues;
  /** Validation rules applied to this parameter's value. */
  validations?: ParameterValidation[];
  /** Dependencies on other parameters (requires or conflicts-with relationships). */
  dependencies?: ParameterDependency[];
}

export type ExclusionType = "mutual_exclusive" | "required_one_of";

export interface ExclusionGroup {
  /** Unique identifier for this exclusion group. */
  key?: string;
  /** Human-readable name for this exclusion group. */
  displayName: string;
  /** Whether parameters in this group are mutually exclusive or one is required. */
  exclusionType: ExclusionType;
  /** Keys of the parameters that participate in this exclusion group. */
  parameterKeys: string[];
}

export interface Tool {
  /** Unique binary name for the tool that it can be invoked from the command line (e.g. "httpx"). */
  binaryName: string;
  /** Human-readable display name for the tool (e.g. "HTTPx"). */
  displayName: string;
  /** Whether the root tool invocation opens an interactive session or prompt. */
  interactive?: boolean;
  /** General information about the tool such as description, version, and URL. */
  info?: ToolInfo;
  /** Structured installation instructions for the tool. */
  installation?: Installation;
  /**
   * Parameters accepted by the tool itself, before a command is chosen. A tool's own flags live
   * here; do not model the root invocation as a command named after the binary, or the root would
   * be described twice.
   */
  parameters: Parameter[];
  /** List of all commands and subcommands defined for this tool. */
  commands: Command[];
  /** Groups of the tool's own parameters with mutual exclusion or required-one-of constraints. */
  exclusionGroups?: ExclusionGroup[];
  /** Arbitrary metadata attached to the tool. */
  metadata?: ToolMetadata;
}

import type {
  Command,
  ExclusionGroup,
  Parameter,
  ParameterValue,
  Tool,
} from "@/components/commandly/types/tool";

export const slugify = (text: string): string => {
  return text
    .toString()
    .toLowerCase()
    .trim()
    .replace(/\s+/g, "-") // Replace spaces with -
    .replace(/[^\w-]+/g, "") // Remove all non-word chars
    .replace(/--+/g, "-") // Replace multiple - with single -
    .replace(/^-+/, "") // Trim - from start of text
    .replace(/-+$/, ""); // Trim - from end of text
};

const flattenCommands = (commands: Command[], sink: Command[] = []): Command[] => {
  for (const command of commands) {
    sink.push(command);
    if (command.commands?.length) flattenCommands(command.commands, sink);
  }
  return sink;
};

/** Every command in the tool, depth-first, each parent before its children. */
export const getAllCommands = (tool: Tool): Command[] => flattenCommands(tool.commands ?? []);

/** Every command beneath `command`, depth-first. */
export const getAllSubcommands = (command: Command): Command[] =>
  flattenCommands(command.commands ?? []);

/** The command with this key anywhere in the tree. */
export const findCommand = (tool: Tool, key: string): Command | undefined =>
  getAllCommands(tool).find((command) => command.key === key);

/**
 * The command to show when the caller has not chosen one: the command named after the binary when
 * there is one, otherwise the first command in the tree.
 */
export const getDefaultCommand = (tool: Tool): Command | null => {
  const commands = getAllCommands(tool);
  return (
    commands.find(
      (command) => command.displayName.toLowerCase() === tool.binaryName.toLowerCase(),
    ) ??
    commands[0] ??
    null
  );
};

/** The chain of commands from the outermost ancestor down to the one with this key. */
export const getCommandChain = (tool: Tool, key: string): Command[] => {
  const walk = (commands: Command[], path: Command[]): Command[] | null => {
    for (const command of commands) {
      const next = [...path, command];
      if (command.key === key) return next;
      const found = walk(command.commands ?? [], next);
      if (found) return found;
    }
    return null;
  };
  return walk(tool.commands ?? [], []) ?? [];
};

export const getCommandPath = (command: Command, tool: Tool): string => {
  const chain = getCommandChain(tool, command.key);
  if (chain.length === 0) return command.displayName;
  return chain.map((step) => step.displayName).join(" ");
};

/**
 * A recursive parameter is inherited: it belongs to its command and to every command below it.
 * Root-scoped, it is inherited by the whole tree.
 */
export const isInheritedParameter = (param: Parameter): boolean => param.recursive === true;

/**
 * Resolves the parameters that apply to the currently selected command: its own parameters,
 * plus those inherited from its ancestors via `recursive`, outermost ancestor first.
 */
export const resolveApplicableParameters = (
  tool: Tool,
  selectedCommand?: Command | null,
): Parameter[] => {
  const rootParameters = tool.parameters ?? [];

  if (!selectedCommand) return rootParameters;

  // Tool-level recursive parameters are inherited by every command in the tree.
  const resolved: Parameter[] = rootParameters.filter(isInheritedParameter);
  const chain = getCommandChain(tool, selectedCommand.key);

  for (const command of chain) {
    for (const parameter of command.parameters ?? []) {
      if (command.key === selectedCommand.key || parameter.recursive) {
        resolved.push(parameter);
      }
    }
  }

  return resolved;
};

/** The parameters declared directly on a command, or on the root invocation when `commandKey` is null. */
export const getCommandParameters = (tool: Tool, commandKey: string | null): Parameter[] => {
  if (commandKey === null) return tool.parameters ?? [];
  return findCommand(tool, commandKey)?.parameters ?? [];
};

/** The exclusion groups declared directly on a command, or on the root invocation when `commandKey` is null. */
export const getExclusionGroups = (tool: Tool, commandKey: string | null): ExclusionGroup[] => {
  if (commandKey === null) return tool.exclusionGroups ?? [];
  return findCommand(tool, commandKey)?.exclusionGroups ?? [];
};

/** Every exclusion group in the tool, root invocation first, in command order. */
export const getAllExclusionGroups = (tool: Tool): ExclusionGroup[] =>
  (tool.exclusionGroups ?? []).concat(
    getAllCommands(tool).flatMap((command) => command.exclusionGroups ?? []),
  );

/** Whether a parameter's current value counts as provided. */
export const hasParameterValue = (value: ParameterValue | undefined): boolean =>
  value !== undefined &&
  value !== "" &&
  value !== false &&
  !(Array.isArray(value) && value.every((entry) => entry === ""));

/**
 * The exclusion groups that constrain a selection: those with at least one member among the
 * parameters that apply to `selectedCommand`.
 */
export const resolveExclusionGroups = (
  tool: Tool,
  selectedCommand?: Command | null,
): ExclusionGroup[] => {
  const applicable = new Set(resolveApplicableParameters(tool, selectedCommand).map((p) => p.key));
  return getAllExclusionGroups(tool).filter((group) =>
    group.parameterKeys.some((key) => applicable.has(key)),
  );
};

/**
 * The parameters a mutually exclusive group rules out, keyed by parameter, given what is
 * provided. Its members are alternatives to one another, so once one is provided every other
 * member is ruled out; the first provided member of each group keeps its place.
 */
export const excludedParameters = (
  groups: ExclusionGroup[],
  values: Record<string, ParameterValue>,
): Map<string, ExclusionGroup> => {
  const excluded = new Map<string, ExclusionGroup>();
  for (const group of groups) {
    if (group.exclusionType !== "mutual_exclusive") continue;
    const [provided] = group.parameterKeys.filter((key) => hasParameterValue(values[key]));
    if (provided === undefined) continue;
    for (const key of group.parameterKeys) {
      if (key !== provided) excluded.set(key, group);
    }
  }
  return excluded;
};

/** The parameters a `required_one_of` group makes mandatory, while none of its members is provided. */
export const requiredParameterKeys = (
  groups: ExclusionGroup[],
  values: Record<string, ParameterValue>,
): Set<string> => {
  const required = new Set<string>();
  for (const group of groups) {
    if (group.exclusionType !== "required_one_of") continue;
    if (group.parameterKeys.some((key) => hasParameterValue(values[key]))) continue;
    for (const key of group.parameterKeys) required.add(key);
  }
  return required;
};

/** Every parameter in the tool, root invocation first, in command order. */
export const getAllParameters = (tool: Tool): Parameter[] =>
  (tool.parameters ?? []).concat(
    getAllCommands(tool).flatMap((command) => command.parameters ?? []),
  );

/**
 * Rewrites a command tree bottom-up, handing `transform` each command with its children already
 * mapped. Walks that drop commands need their own traversal, since this one is one-to-one.
 */
export const mapCommandTree = (
  commands: Command[],
  transform: (command: Command) => Command,
): Command[] =>
  commands.map((command) =>
    transform(
      command.commands?.length
        ? { ...command, commands: mapCommandTree(command.commands, transform) }
        : command,
    ),
  );

/** Applies `update` to the command with `key` anywhere in the tree, leaving every other command alone. */
export const updateCommand = (
  tool: Tool,
  key: string,
  update: (command: Command) => Command,
): Tool => ({
  ...tool,
  commands: mapCommandTree(tool.commands ?? [], (command) =>
    command.key === key ? update(command) : command,
  ),
});

/** Drops the command with `key` and everything nested beneath it. */
export const removeCommand = (tool: Tool, key: string): Tool => ({
  ...tool,
  commands: dropCommand(tool.commands ?? [], key),
});

const dropCommand = (commands: Command[], key: string): Command[] =>
  commands
    .filter((command) => command.key !== key)
    .map((command) =>
      command.commands?.length
        ? { ...command, commands: dropCommand(command.commands, key) }
        : command,
    );

/**
 * Applies `update` to the parameters an owner declares: the command with `ownerKey`, or the tool's
 * own parameters when it is null. `recursive` decides where a parameter *applies*, never where it
 * is written, so this deliberately does not touch inherited parameters.
 */
export const updateParameters = (
  tool: Tool,
  ownerKey: string | null,
  update: (parameters: Parameter[]) => Parameter[],
): Tool =>
  ownerKey === null
    ? { ...tool, parameters: update(tool.parameters ?? []) }
    : updateCommand(tool, ownerKey, (command) => ({
        ...command,
        parameters: update(command.parameters ?? []),
      }));

/** Same as {@link updateParameters} for the exclusion groups an owner declares. */
export const updateExclusionGroups = (
  tool: Tool,
  ownerKey: string | null,
  update: (groups: ExclusionGroup[]) => ExclusionGroup[],
): Tool =>
  ownerKey === null
    ? { ...tool, exclusionGroups: update(tool.exclusionGroups ?? []) }
    : updateCommand(tool, ownerKey, (command) => ({
        ...command,
        exclusionGroups: update(command.exclusionGroups ?? []),
      }));

/** Drops the parameter with `key` from the set an owner declares. */
export const removeParameter = (tool: Tool, ownerKey: string | null, key: string): Tool =>
  updateParameters(tool, ownerKey, (parameters) =>
    parameters.filter((parameter) => parameter.key !== key),
  );

/** Reorders `items` so the given keys take those positions, stamping each item's `sortOrder`. */
export const reorderByKeys = <T extends { key: string; sortOrder?: number }>(
  items: T[],
  keys: string[],
): T[] => {
  const slots: number[] = [];
  const byKey = new Map<string, T>();
  const reordered = new Set(keys);

  items.forEach((item, index) => {
    byKey.set(item.key, item);
    if (reordered.has(item.key)) slots.push(index);
  });

  const next = [...items];
  keys.forEach((key, sortOrder) => {
    const slot = slots[sortOrder];
    const item = byKey.get(key);
    if (slot !== undefined && item) next[slot] = { ...item, sortOrder };
  });
  return next;
};

import type { Command, ExclusionGroup, Parameter, Tool } from "@/components/commandly/types/tool";
import { mapCommandTree, slugify } from "@/components/commandly/utils/tool";

/** URL of the published JSON Schema for tool files, written to `$schema` on export. */
export const SCHEMA_URL = "https://commandly.divyeshio.in/specification/tool.json";

function isEmptyArray(value: unknown): boolean {
  return Array.isArray(value) && value.length === 0;
}

function isEmptyObject(value: unknown): boolean {
  return (
    value != null &&
    typeof value === "object" &&
    !Array.isArray(value) &&
    Object.keys(value).length === 0
  );
}

/**
 * How a tool is normalised for output. The published JSON keeps the defaults the user typed; the
 * file written to disk drops them.
 */
interface CleanToolOptions {
  /** Drop `metadata`, which the published JSON does not carry. */
  removeMetadata: boolean;
  /** Drop fields whose value already encodes the default. */
  removeDefaults: boolean;
}

function cleanParameter(param: Parameter, options: CleanToolOptions): Parameter {
  const cleaned: Parameter = { ...param };

  if (options.removeDefaults) {
    if (cleaned.isRequired === false) delete cleaned.isRequired;
    if (cleaned.isRepeatable === false) delete cleaned.isRepeatable;
    if (cleaned.recursive === false) delete cleaned.recursive;
    if (cleaned.keyValueSeparator === " ") delete cleaned.keyValueSeparator;
    if (cleaned.arraySeparator === "," && cleaned.isRepeatable !== true)
      delete cleaned.arraySeparator;

    if (isEmptyArray(cleaned.aliases)) delete cleaned.aliases;
    if (!cleaned.enum || isEmptyArray(cleaned.enum.values)) delete cleaned.enum;
    if (isEmptyArray(cleaned.validations)) delete cleaned.validations;
    if (isEmptyArray(cleaned.dependencies)) delete cleaned.dependencies;
  }

  if (options.removeMetadata) {
    delete cleaned.metadata;
  } else if (cleaned.metadata) {
    const metadata = { ...cleaned.metadata };
    if (isEmptyArray(metadata.tags)) delete metadata.tags;
    if (isEmptyObject(metadata)) delete cleaned.metadata;
    else cleaned.metadata = metadata;
  }

  return cleaned;
}

function cleanCommandTree(commands: Command[], options: CleanToolOptions): Command[] {
  return mapCommandTree(commands, (command) => {
    const cleaned: Command = { ...command };

    if (options.removeDefaults) {
      if (cleaned.interactive === false) delete cleaned.interactive;
      if (cleaned.exclusionGroups?.length === 0) delete cleaned.exclusionGroups;
    }
    if (cleaned.parameters) {
      cleaned.parameters = cleaned.parameters.map((param) => cleanParameter(param, options));
    }
    if (cleaned.commands?.length === 0) delete cleaned.commands;

    return cleaned;
  });
}

/** The published JSON: the user's defaults are kept, `metadata` is dropped. */
const EXPORT_OPTIONS: CleanToolOptions = { removeMetadata: true, removeDefaults: false };

export const exportToStructuredJSON = (tool: Tool) => ({
  $schema: SCHEMA_URL,
  binaryName: tool.binaryName,
  displayName: tool.displayName,
  interactive: tool.interactive,
  info: tool.info,
  installation: tool.installation,
  parameters: tool.parameters.map((param) => cleanParameter(param, EXPORT_OPTIONS)),
  commands: cleanCommandTree(tool.commands, EXPORT_OPTIONS),
  exclusionGroups: tool.exclusionGroups,
  metadata: tool.metadata,
});

/** The tool as it is written to disk or published: `$schema` is added on request. */
export type ToolFile = Tool & { $schema?: string };

export interface FixToolOptions {
  addSchema?: boolean;
  removeMetadata?: boolean;
}

/** Normalises a tool into the shape the specification expects, dropping defaults that say nothing. */
export function fixTool(tool: Tool, options?: FixToolOptions): ToolFile {
  const cleanOptions: CleanToolOptions = {
    removeMetadata: options?.removeMetadata ?? false,
    removeDefaults: true,
  };

  const cleaned: ToolFile = { ...tool };

  if (options?.addSchema) cleaned.$schema = SCHEMA_URL;
  if (cleaned.interactive === false) delete cleaned.interactive;
  if (cleanOptions.removeMetadata || isEmptyObject(cleaned.metadata)) delete cleaned.metadata;
  if (isEmptyArray(cleaned.exclusionGroups)) delete cleaned.exclusionGroups;
  if (isEmptyArray(cleaned.installation?.sources)) delete cleaned.installation;

  cleaned.parameters = (cleaned.parameters ?? []).map((param) =>
    cleanParameter(param, cleanOptions),
  );
  cleaned.commands = cleanCommandTree(cleaned.commands ?? [], cleanOptions);

  return cleaned;
}

/** A group always needs a key: that is how the editor finds it again to edit or remove it. */
const slugifyGroupKey = (group: ExclusionGroup): ExclusionGroup => ({
  ...group,
  key: slugify(group.displayName),
});

/**
 * Rebuilds the keys a generated tool may have drifted on: command and exclusion-group keys become
 * slugs of their display names. Parameter keys are the flags themselves, so they are left alone.
 */
export const normalizeKeys = (tool: Tool): Tool => ({
  ...tool,
  ...(tool.exclusionGroups ? { exclusionGroups: tool.exclusionGroups.map(slugifyGroupKey) } : {}),
  commands: mapCommandTree(tool.commands ?? [], (command) => ({
    ...command,
    key: slugify(command.displayName),
    ...(command.exclusionGroups
      ? { exclusionGroups: command.exclusionGroups.map(slugifyGroupKey) }
      : {}),
  })),
});

export type DiffLineType = "same" | "added" | "removed";

export interface DiffLine {
  type: DiffLineType;
  text: string;
}

/** An unchanged run the display collapsed into a single row. */
export interface DiffGap {
  type: "gap";
  /** How many unchanged lines the gap stands for. */
  count: number;
}

/** A diff as the display wants it: a line, or a collapsed run of unchanged lines. */
export type DiffRow = DiffLine | DiffGap;

/**
 * Above this many differing lines on either side the comparison falls back to a plain
 * replacement: the longest-common-subsequence matrix is quadratic in memory and time. Only the
 * lines between the shared head and tail are ever compared, so a localised edit to a very large
 * file still diffs exactly.
 */
export const MAX_DIFF_LINES = 2000;

/** How many unchanged lines the display keeps on either side of a change. */
export const DIFF_CONTEXT_LINES = 3;

const same = (text: string): DiffLine => ({ type: "same", text });

/** How many leading lines `a` and `b` have in common. */
const sharedHead = (a: string[], b: string[]): number => {
  const max = Math.min(a.length, b.length);
  let head = 0;
  while (head < max && a[head] === b[head]) head++;
  return head;
};

/** How many trailing lines `a` and `b` have in common, past the `head` already claimed. */
const sharedTail = (a: string[], b: string[], head: number): number => {
  const max = Math.min(a.length, b.length) - head;
  let tail = 0;
  while (tail < max && a[a.length - 1 - tail] === b[b.length - 1 - tail]) tail++;
  return tail;
};

const replaceBlock = (removed: string[], added: string[]): DiffLine[] => [
  ...removed.map((text): DiffLine => ({ type: "removed", text })),
  ...added.map((text): DiffLine => ({ type: "added", text })),
];

/** The longest-common-subsequence comparison of two line arrays. */
const compareLines = (before: string[], after: string[]): DiffLine[] => {
  if (before.length > MAX_DIFF_LINES || after.length > MAX_DIFF_LINES) {
    return replaceBlock(before, after);
  }

  const rows = before.length;
  const columns = after.length;
  const lengths = Array.from({ length: rows + 1 }, () => new Array<number>(columns + 1).fill(0));

  for (let i = 1; i <= rows; i++) {
    for (let j = 1; j <= columns; j++) {
      lengths[i][j] =
        before[i - 1] === after[j - 1]
          ? lengths[i - 1][j - 1] + 1
          : Math.max(lengths[i - 1][j], lengths[i][j - 1]);
    }
  }

  const diff: DiffLine[] = [];
  let i = rows;
  let j = columns;

  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && before[i - 1] === after[j - 1]) {
      diff.unshift(same(before[i - 1]));
      i--;
      j--;
    } else if (j > 0 && (i === 0 || lengths[i][j - 1] >= lengths[i - 1][j])) {
      diff.unshift({ type: "added", text: after[j - 1] });
      j--;
    } else {
      diff.unshift({ type: "removed", text: before[i - 1] });
      i--;
    }
  }

  return diff;
};

/** A line-level diff of two texts, unchanged lines included. */
export const diffLines = (before: string, after: string): DiffLine[] => {
  const beforeLines = before.split("\n");
  const afterLines = after.split("\n");

  const head = sharedHead(beforeLines, afterLines);
  const tail = sharedTail(beforeLines, afterLines, head);

  return [
    ...beforeLines.slice(0, head).map(same),
    ...compareLines(
      beforeLines.slice(head, beforeLines.length - tail),
      afterLines.slice(head, afterLines.length - tail),
    ),
    ...beforeLines.slice(beforeLines.length - tail).map(same),
  ];
};

/**
 * The rows a diff should be drawn with: an unchanged run longer than two context windows collapses
 * to a single gap, so a large file with a small edit stays readable.
 */
export const collapseUnchanged = (diff: DiffLine[], context = DIFF_CONTEXT_LINES): DiffRow[] => {
  const rows: DiffRow[] = [];

  for (let index = 0; index < diff.length;) {
    if (diff[index].type !== "same") {
      rows.push(diff[index]);
      index++;
      continue;
    }

    let end = index;
    while (end < diff.length && diff[end].type === "same") end++;

    if (end - index > context * 2) {
      rows.push(
        ...diff.slice(index, index + context),
        { type: "gap", count: end - index - context * 2 },
        ...diff.slice(end - context, end),
      );
    } else {
      rows.push(...diff.slice(index, end));
    }
    index = end;
  }

  return rows;
};

/** Writes `text` to the clipboard, rejecting when the browser refuses access. */
export async function writeClipboard(text: string): Promise<void> {
  if (!navigator.clipboard) throw new Error("Clipboard unavailable");
  await navigator.clipboard.writeText(text);
}

export type JsonValueType = "object" | "array" | "string" | "number" | "boolean" | "null" | "other";

const IDENTIFIER = /^[A-Za-z_$][\w$]*$/;

/** How many matches a search collects before giving up. */
const MAX_MATCHES = 2000;

export function typeOf(value: unknown): JsonValueType {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  switch (typeof value) {
    case "object":
      return "object";
    case "string":
      return "string";
    case "number":
    case "bigint":
      return "number";
    case "boolean":
      return "boolean";
    default:
      return "other";
  }
}

export const isBranch = (type: JsonValueType) => type === "object" || type === "array";

export function entries(value: unknown): [string | number, unknown][] {
  if (Array.isArray(value)) return value.map((item, index) => [index, item]);
  if (value && typeof value === "object") return Object.entries(value as Record<string, unknown>);
  return [];
}

/** The dot/bracket path of a child within its parent, e.g. `root.items[2].name`. */
export const childPath = (parent: string, key: string | number) =>
  typeof key === "number"
    ? `${parent}[${key}]`
    : IDENTIFIER.test(key)
      ? `${parent}.${key}`
      : `${parent}[${JSON.stringify(key)}]`;

/** Whether `id` is `ancestor` or sits beneath it. */
export const within = (ancestor: string, id: string) =>
  id === ancestor || id.startsWith(`${ancestor}.`) || id.startsWith(`${ancestor}[`);

export function primitiveText(value: unknown, type: JsonValueType) {
  if (type === "string") return value as string;
  if (type === "null") return "null";
  return String(value);
}

/** The text a copy action should place on the clipboard for this value. */
export function copyText(value: unknown, type: JsonValueType) {
  if (type === "string") return value as string;
  if (isBranch(type)) return JSON.stringify(value, null, 2);
  return primitiveText(value, type);
}

const plural = (count: number, one: string, many: string) => `${count} ${count === 1 ? one : many}`;

export const countLabel = (type: JsonValueType, count: number) =>
  type === "array" ? plural(count, "item", "items") : plural(count, "key", "keys");

/** The paths of every branch in the data, root first. */
export function allBranches(data: unknown, rootName: string) {
  const out: string[] = [];
  const visit = (value: unknown, id: string) => {
    if (!isBranch(typeOf(value))) return;
    out.push(id);
    for (const [key, child] of entries(value)) visit(child, childPath(id, key));
  };
  visit(data, rootName);
  return out;
}

/** The paths of every branch within the first `depth` levels. */
export function branchesToDepth(data: unknown, rootName: string, depth: number) {
  const out: string[] = [];
  const visit = (value: unknown, id: string, level: number) => {
    if (level >= depth || !isBranch(typeOf(value))) return;
    out.push(id);
    for (const [key, child] of entries(value)) visit(child, childPath(id, key), level + 1);
  };
  visit(data, rootName, 0);
  return out;
}

export interface SearchResult {
  /** The paths of every matching row, in document order. */
  matches: string[];
  /** The branches that must be open for every match to be reachable. */
  ancestors: Set<string>;
  /** Per branch, how many of its children must be listed for every match to be reachable. */
  needed: Map<string, number>;
}

/** A case-insensitive search over keys and primitive values. */
export function searchJson(data: unknown, rootName: string, needle: string): SearchResult {
  const matches: string[] = [];
  const ancestors = new Set<string>();
  const needed = new Map<string, number>();
  const frames: [string, number][] = [];
  const visit = (value: unknown, id: string, name: string | number | null) => {
    if (matches.length >= MAX_MATCHES) return;
    const type = typeOf(value);
    const inKey = typeof name === "string" && name.toLowerCase().includes(needle);
    const inValue = !isBranch(type) && primitiveText(value, type).toLowerCase().includes(needle);
    if (inKey || inValue) {
      matches.push(id);
      for (const [frame, index] of frames) {
        ancestors.add(frame);
        needed.set(frame, Math.max(needed.get(frame) ?? 0, index + 1));
      }
    }
    if (!isBranch(type)) return;
    entries(value).forEach(([key, child], index) => {
      frames.push([id, index]);
      visit(child, childPath(id, key), key);
      frames.pop();
    });
  };
  visit(data, rootName, null);
  return { matches, ancestors, needed };
}
